import{_ as l,a0 as p,w as o,s as d,ao as r,I as t,x as e,a1 as n,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const w=JSON.parse('{"title":"如何在 Linux 上重命名一組文件 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 上重命名一組文件 | LCTT (201909) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Linux 上重命名一組文件 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 上重命名一組文件 | LCTT (201909) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201909/20190826 How to rename a group of files on Linux","title":"如何在 Linux 上重命名一組文件","tag":"201909","desc":""},"relativePath":"201909/20190826 How to rename a group of files on Linux.md","filePath":"[post].md"}'),c={name:"201909/20190826 How to rename a group of files on Linux.md"};function h(g,s,u,m,k,b){const a=p("Link");return o(),d("div",null,[s[15]||(s[15]=r(`<h1 id="如何在-linux-上重命名一組文件" tabindex="-1">如何在 Linux 上重命名一組文件 <a class="header-anchor" href="#如何在-linux-上重命名一組文件" aria-label="Permalink to “如何在 Linux 上重命名一組文件”">​</a></h1><blockquote><p>要用單個命令重命名一組文件，請使用 rename 命令。它需要使用正則表達式，並且可以在開始前告訴你會有什麼更改。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/201909/03/005333hfm8yf90m2gm800g.jpg" alt=""></p><p>幾十年來，Linux 用户一直使用 <code>mv</code> 命令重命名文件。它很簡單，並且能做到你要做的。但有時你需要重命名一大組文件。在這種情況下，<code>rename</code> 命令可以使這個任務更容易。它只需要一些正則表達式的技巧。</p><p>與 <code>mv</code> 命令不同，<code>rename</code> 不允許你簡單地指定舊名稱和新名稱。相反，它使用類似於 Perl 中的正則表達式。在下面的例子中，<code>s</code> 指定我們將第一個字符串替換為第二個字符串（舊的），從而將 <code>this.new</code> 變為 <code>this.old</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ rename &#39;s/new/old/&#39; this.new</span></span>
<span class="line"><span>$ ls this*</span></span>
<span class="line"><span>this.old</span></span></code></pre></div><p>使用 <code>mv this.new this.old</code> 可以更容易地進行更改一個，但是將字符串 <code>this</code> 變成通配符 <code>*</code>，你可以用一條命令將所有的 <code>*.new</code> 文件重命名為 <code>*.old</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls *.new</span></span>
<span class="line"><span>report.new  schedule.new  stats.new  this.new</span></span>
<span class="line"><span>$ rename &#39;s/new/old/&#39; *.new</span></span>
<span class="line"><span>$ ls *.old</span></span>
<span class="line"><span>report.old  schedule.old  stats.old  this.old</span></span></code></pre></div><p>正如你所料，<code>rename</code> 命令不限於更改文件擴展名。如果你需要將名為 <code>report.*</code> 的文件更改為 <code>review.*</code>，那麼可以使用以下命令做到：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ rename &#39;s/report/review/&#39; *</span></span></code></pre></div><p>正則表達式中的字符串可以更改文件名的任何部分，無論是文件名還是擴展名。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ rename &#39;s/123/124/&#39; *</span></span>
<span class="line"><span>$ ls *124*</span></span>
<span class="line"><span>status.124  report124.txt</span></span></code></pre></div><p>如果你在 <code>rename</code> 命令中添加 <code>-v</code> 選項，那麼該命令將提供一些反饋，以便你可以看到所做的更改，或許會包含你沒注意的。這讓你注意到並按需還原更改。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ rename -v &#39;s/123/124/&#39; *</span></span>
<span class="line"><span>status.123 renamed as status.124</span></span>
<span class="line"><span>report123.txt renamed as report124.txt</span></span></code></pre></div><p>另一方面，使用 <code>-n</code>（或 <code>--nono</code>）選項會使 <code>rename</code> 命令告訴你將要做的但不會實際做的更改。這可以讓你免於執行不不想要的操作，然後再還原更改。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ rename -n &#39;s/old/save/&#39; *</span></span>
<span class="line"><span>rename(logger.man-old, logger.man-save)</span></span>
<span class="line"><span>rename(lyrics.txt-old, lyrics.txt-save)</span></span>
<span class="line"><span>rename(olderfile-, saveerfile-)</span></span>
<span class="line"><span>rename(oldfile, savefile)</span></span>
<span class="line"><span>rename(review.old, review.save)</span></span>
<span class="line"><span>rename(schedule.old, schedule.save)</span></span>
<span class="line"><span>rename(stats.old, stats.save)</span></span>
<span class="line"><span>rename(this.old, this.save)</span></span></code></pre></div><p>如果你對這些更改滿意，那麼就可以運行不帶 <code>-n</code> 選項的命令來更改文件名。</p><p>但請注意，正則表達式中的 <code>.</code> <strong>不會</strong>被視為句點，而是作為匹配任何字符的通配符。上面和下面的示例中的一些更改可能不是輸入命令的人希望的。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ rename -n &#39;s/.old/.save/&#39; *</span></span>
<span class="line"><span>rename(logger.man-old, logger.man.save)</span></span>
<span class="line"><span>rename(lyrics.txt-old, lyrics.txt.save)</span></span>
<span class="line"><span>rename(review.old, review.save)</span></span>
<span class="line"><span>rename(schedule.old, schedule.save)</span></span>
<span class="line"><span>rename(stats.old, stats.save)</span></span>
<span class="line"><span>rename(this.old, this.save)</span></span></code></pre></div><p>為確保句點按照字面意思執行，請在它的前面加一個反斜槓。這將使其不被解釋為通配符並匹配任何字符。請注意，進行此更改時，僅選擇了 <code>.old</code> 文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ rename -n &#39;s/\\.old/.save/&#39; *</span></span>
<span class="line"><span>rename(review.old, review.save)</span></span>
<span class="line"><span>rename(schedule.old, schedule.save)</span></span>
<span class="line"><span>rename(stats.old, stats.save)</span></span>
<span class="line"><span>rename(this.old, this.save)</span></span></code></pre></div><p>下面的命令會將文件名中的所有大寫字母更改為小寫，除了使用 <code>-n</code> 選項來確保我們在命令執行之前檢查將做的修改。注意在正則表達式中使用了 <code>y</code>，這是改變大小寫所必需的。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ rename -n &#39;y/A-Z/a-z/&#39; W*</span></span>
<span class="line"><span>rename(WARNING_SIGN.pdf, warning_sign.pdf)</span></span>
<span class="line"><span>rename(Will_Gardner_buttons.pdf, will_gardner_buttons.pdf)</span></span>
<span class="line"><span>rename(Wingding_Invites.pdf, wingding_invites.pdf)</span></span>
<span class="line"><span>rename(WOW-buttons.pdf, wow-buttons.pdf)</span></span></code></pre></div><p>在上面的例子中，我們將所有大寫字母更改為了小寫，但這僅對以大寫字母 <code>W</code> 開頭的文件名。</p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>當你需要重命名大量文件時，<code>rename</code> 命令非常有用。請注意不要做比預期更多的更改。請記住，<code>-n</code>（或者 <code>--nono</code>）選項可以幫助你避免耗時的錯誤。</p><hr>`,27)),t("p",null,[s[1]||(s[1]=e("via: ",-1)),n(a,{href:"https://www.networkworld.com/article/3433865/how-to-rename-a-group-of-files-on-linux.html"},{default:i(()=>[...s[0]||(s[0]=[e("https://www.networkworld.com/article/3433865/how-to-rename-a-group-of-files-on-linux.html",-1)])]),_:1})]),t("p",null,[s[6]||(s[6]=e("作者：",-1)),n(a,{href:"https://www.networkworld.com/author/Sandra-Henry_Stocker/"},{default:i(()=>[...s[2]||(s[2]=[e("Sandra Henry-Stocker",-1)])]),_:1}),s[7]||(s[7]=e(" 選題：",-1)),n(a,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[3]||(s[3]=[e("lujun9972",-1)])]),_:1}),s[8]||(s[8]=e(" 譯者：",-1)),n(a,{href:"https://github.com/geekpi"},{default:i(()=>[...s[4]||(s[4]=[e("geekpi",-1)])]),_:1}),s[9]||(s[9]=e(" 校對：",-1)),n(a,{href:"https://github.com/wxy"},{default:i(()=>[...s[5]||(s[5]=[e("wxy",-1)])]),_:1})]),t("p",null,[s[12]||(s[12]=e("本文由 ",-1)),n(a,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[10]||(s[10]=[e("LCTT",-1)])]),_:1}),s[13]||(s[13]=e(" 原創編譯，",-1)),n(a,{href:"https://linux.cn/"},{default:i(()=>[...s[11]||(s[11]=[e("Linux中國",-1)])]),_:1}),s[14]||(s[14]=e(" 榮譽推出",-1))])])}const x=l(c,[["render",h]]);export{w as __pageData,x as default};
